try:
    # outputs should be a list of section objects
    if not isinstance(outputs, list):
        return Feedback(value=False, rationale=f"Output is not a list, got {type(outputs).__name__}")

    if len(outputs) == 0:
        return Feedback(value=False, rationale="Output is an empty list")

    issues = []
    for i, item in enumerate(outputs):
        if not isinstance(item, dict):
            issues.append(f"Item {i} is not a dict")
            continue

        # Check required top-level fields
        for field in ["document_title", "sections"]:
            if field not in item:
                issues.append(f"Item {i} missing '{field}'")

        # Check sections structure
        sections = item.get("sections", [])
        if not isinstance(sections, list):
            issues.append(f"Item {i}: 'sections' is not a list")
        else:
            for j, sec in enumerate(sections):
                if not isinstance(sec, dict):
                    issues.append(f"Item {i}, section {j}: not a dict")
                    continue
                for sec_field in ["id", "title", "level", "summary"]:
                    if sec_field not in sec:
                        issues.append(f"Item {i}, section {j}: missing '{sec_field}'")

    if issues:
        return Feedback(value=False, rationale="; ".join(issues[:5]))

    return Feedback(value=True, rationale=f"Valid JSON schema with {len(outputs)} document(s) and {sum(len(d.get('sections', [])) for d in outputs)} total sections")
except Exception as e:
    return Feedback(value=False, rationale=f"Validation error: {str(e)}")
